/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_ediAmount">_ediAmount</param>
/// <param name = "_custAccount">_custAccount</param>
/// <returns></returns>
public boolean mustBeUpload(Amount      _editAmount, CustAccount _custAccount)
{
    boolean mustbeUpload = next mustbeUpload(_editAmount,_custAccount);

    mustbeUpload = mustbeUpload && this.checkExceptions(_custAccount);

    return mustbeUpload;
}

/// <summary>
/// designed from
/// </summary>
/// <param name = "_custAccount">_custAccount</param>
/// <returns>boolean</returns>
public boolean checkExceptions(CustAccount  _custAccount)
{
    AVACustVendAssignemtExceptions      custVendExceptions;
    boolean                             ret = false;
    ;

    select firstonly custVendExceptions
        where custVendExceptions.CustVendAssignmentRefRecId == this.RecId
           && custVendExceptions.CustAccount                == _custAccount;

    if (!custVendExceptions)
    {
        ret = true;
    }

    return ret;

}

/// <summary>
/// N.Freidenberger TASK 0010906
/// </summary>
/// <returns>Name</returns>
public display Name name()
{
    Name name = next name();

    if (this.AVACustRel2TOS)
    {
        name = KCS_TOSTable::find(this.CustVendAC).Description;
    }
    return name;
}
